var findMedianSortedArrays = function(nums1, nums2) {
    if (nums1.length > nums2.length) {
        const tmp = nums1; nums1 = nums2; nums2 = tmp;
    }
    const m = nums1.length, n = nums2.length;
    const leftSize = Math.floor((m + n + 1) / 2);
    let lo = 0, hi = m;
    while (lo <= hi) {
        const cut1 = Math.floor((lo + hi) / 2);
        const cut2 = leftSize - cut1;
        const left1 = cut1 ? nums1[cut1 - 1] : -Infinity;
        const right1 = cut1 < m ? nums1[cut1] : Infinity;
        const left2 = cut2 ? nums2[cut2 - 1] : -Infinity;
        const right2 = cut2 < n ? nums2[cut2] : Infinity;
        if (left1 <= right2 && left2 <= right1) {
            if ((m + n) % 2) return Math.max(left1, left2);
            return (Math.max(left1, left2) + Math.min(right1, right2)) / 2;
        }
        if (left1 > right2) hi = cut1 - 1;
        else lo = cut1 + 1;
    }
    throw new Error('Inputs must be sorted and not both empty');
};

