from typing import List

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        left_size = (m + n + 1) // 2
        lo, hi = 0, m

        while lo <= hi:
            cut1 = (lo + hi) // 2
            cut2 = left_size - cut1

            left1 = nums1[cut1 - 1] if cut1 else float("-inf")
            right1 = nums1[cut1] if cut1 < m else float("inf")
            left2 = nums2[cut2 - 1] if cut2 else float("-inf")
            right2 = nums2[cut2] if cut2 < n else float("inf")

            if left1 <= right2 and left2 <= right1:
                if (m + n) % 2:
                    return float(max(left1, left2))
                return (max(left1, left2) + min(right1, right2)) / 2.0
            if left1 > right2:
                hi = cut1 - 1
            else:
                lo = cut1 + 1

        raise ValueError("Inputs must be sorted and not both empty")
